"""submitted_image 去掉字符串默认值 + 清理历史占位值。

原来 `default="default_submissionImage.png"` 会让"没上传图片"的提交也拥有
一个 truthy 的文件路径：
  - tasks.py 的 `if not submission.submitted_image` 判空永不生效，
    主观题会把占位图当成学生答卷送给视觉大模型评分；
  - 前端 `if submission.submitted_image` 会渲染出一张根本不存在的图片。
本迁移把字段默认值改为 None，并把历史记录中的占位值清成 NULL。
"""

from django.db import migrations, models

PLACEHOLDER_PATHS = (
    'default_submissionImage.png',
    'submissions/default_submissionImage.png',
)

BATCH_SIZE = 500


def clear_placeholder_images(apps, schema_editor):
    Submission = apps.get_model('gradingModule', 'Submission')

    stale = Submission.objects.filter(
        submitted_image__isnull=False,
        submitted_image__in=PLACEHOLDER_PATHS,
    )

    total = stale.count()
    if not total:
        return

    # 分批置空，避免大表一次 UPDATE 锁太久
    for submission in stale.iterator(chunk_size=BATCH_SIZE):
        submission.submitted_image = None
        submission.save(update_fields=['submitted_image'])

    print(f'  → 清理占位图片引用: {total} 条')


class Migration(migrations.Migration):

    dependencies = [
        ('gradingModule', '0004_normalize_submission_status'),
    ]

    operations = [
        migrations.AlterField(
            model_name='submission',
            name='submitted_image',
            field=models.ImageField(blank=True, default=None, null=True, upload_to='submissions/', verbose_name='提交图片'),
        ),
        migrations.RunPython(clear_placeholder_images, migrations.RunPython.noop),
    ]
